create or replace function finance_private.current_period_calculation_worker_is_trusted() returns boolean language sql stable security definer set search_path='' as $$select false$$;
create or replace function finance_private.current_actor_can_calculate_finance_period(p_actor_id uuid,p_period_id uuid) returns boolean language sql stable security definer set search_path='' as $$select false$$;
revoke all on function finance_private.current_period_calculation_worker_is_trusted() from public,anon,authenticated;revoke all on function finance_private.current_actor_can_calculate_finance_period(uuid,uuid) from public,anon,authenticated;
create or replace function finance_api.authorize_finance_period_calculation(p_period_id uuid,p_permission text) returns jsonb language sql stable security definer set search_path='' as $$select case when p_permission='finance.periods.calculate' and auth.uid() is not null and finance_private.current_actor_can_calculate_finance_period(auth.uid(),fp.id) then pg_catalog.jsonb_build_object('allowed',true,'legalEntityId',fp.legal_entity_id,'dealerAccountId',fp.dealer_account_id,'branchId',fp.branch_id,'parentPeriodId',fp.parent_period_id) else pg_catalog.jsonb_build_object('allowed',false) end from finance.finance_periods fp where fp.id=p_period_id and fp.scope_type='BRANCH'$$;
create or replace function finance_api.queue_finance_period_calculation(p_actor_id uuid,p_period_id uuid,p_legal_entity_id uuid,p_dealer_account_id uuid,p_branch_id uuid,p_source_snapshot_hash text,p_expected_version bigint,p_idempotency_key text,p_intent_hash text,p_correlation_id uuid) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare p finance.finance_periods%rowtype;v_count bigint;v_blocked bigint;v_material text;v_hash text;v_job uuid;v_version bigint;v_existing jsonb;v_existing_hash text;v_payload jsonb;v_payload_hash text;v_previous text;v_audit text;
begin
 if not finance_private.current_period_calculation_worker_is_trusted() then raise exception using errcode='42501',message='period calculation worker denied';end if;
 if p_actor_id is null or p_period_id is null or p_legal_entity_id is null or p_dealer_account_id is null or p_branch_id is null or p_source_snapshot_hash!~'^[a-fA-F0-9]{64}$' or p_expected_version<1 or coalesce(pg_catalog.btrim(p_idempotency_key),'')='' or pg_catalog.length(p_idempotency_key)>200 or p_intent_hash!~'^[a-fA-F0-9]{64}$' or p_correlation_id is null then raise exception using errcode='22023',message='required period calculation fields missing';end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('period-calculation:'||p_period_id::text,0));
 select om.payload,om.payload->>'intentHash' into v_existing,v_existing_hash from finance.outbox_messages om where om.aggregate_type='finance_period' and om.aggregate_id=p_period_id and om.event_type='FINANCE_PERIOD_CALCULATION_QUEUED' and om.payload->>'idempotencyKey'=p_idempotency_key order by om.created_at_utc desc,om.id desc limit 1;
 if found then if v_existing_hash=p_intent_hash then return pg_catalog.jsonb_build_object('outcome','REPLAY','jobId',v_existing->>'jobId','periodId',p_period_id,'status','QUEUED','version',(v_existing->>'version')::bigint,'sourceSnapshotHash',v_existing->>'sourceSnapshotHash');end if;return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 select * into p from finance.finance_periods fp where fp.id=p_period_id for update;if not found then raise exception using errcode='P0002',message='finance period not found';end if;
 if p.scope_type<>'BRANCH' or p.parent_period_id is null or p.legal_entity_id<>p_legal_entity_id or p.dealer_account_id<>p_dealer_account_id or p.branch_id<>p_branch_id then raise exception using errcode='42501',message='branch finance period scope mismatch';end if;
 if p.version<>p_expected_version or p.status not in('OPEN','REOPENED') then return pg_catalog.jsonb_build_object('outcome','CONFLICT','periodId',p.id,'version',p.version);end if;
 select pg_catalog.count(*),pg_catalog.count(*) filter(where se.status in('WAITING_PREDECESSOR','PROCESSING','REJECTED')),pg_catalog.string_agg(se.id::text||':'||se.event_id::text||':'||se.source_system||':'||se.event_type||':'||se.business_date::text||':'||se.payload_hash,'|' order by se.business_date,se.id) into v_count,v_blocked,v_material from finance.source_events se join finance.dealer_accounts da on da.id=p.dealer_account_id and da.dealer_legal_entity_id=se.dealer_legal_entity_id where se.legal_entity_id=p.legal_entity_id and se.branch_id=p.branch_id and se.business_date between p.period_start and p.period_end;
 if v_count=0 or v_blocked>0 then raise exception using errcode='23514',message='period source set is empty or not freezeable';end if;v_hash:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(v_material,'UTF8'),'sha256'),'hex');if v_hash<>pg_catalog.lower(p_source_snapshot_hash) then raise exception using errcode='23514',message='period source snapshot mismatch';end if;
 v_job:=gen_random_uuid();update finance.finance_periods set status='SOURCE_FROZEN',source_snapshot_hash=v_hash,prepared_by=p_actor_id,version=version+1,correlation_id=p_correlation_id where id=p.id and version=p_expected_version returning version into v_version;if not found then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 v_payload:=pg_catalog.jsonb_build_object('jobId',v_job,'periodId',p.id,'parentPeriodId',p.parent_period_id,'dealerAccountId',p.dealer_account_id,'branchId',p.branch_id,'sourceCount',v_count,'sourceSnapshotHash',v_hash,'version',v_version,'idempotencyKey',p_idempotency_key,'intentHash',p_intent_hash);v_payload_hash:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(v_payload::text,'UTF8'),'sha256'),'hex');insert into finance.outbox_messages(id,legal_entity_id,topic,event_type,aggregate_type,aggregate_id,aggregate_version,payload,payload_hash,status,correlation_id) values(v_job,p.legal_entity_id,'finance.period','FINANCE_PERIOD_CALCULATION_QUEUED','finance_period',p.id,v_version,v_payload,v_payload_hash,'PENDING',p_correlation_id);
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('audit:'||p.legal_entity_id::text,0));select ae.integrity_hash into v_previous from finance.audit_events ae where ae.legal_entity_id=p.legal_entity_id order by ae.created_at_utc desc,ae.id desc limit 1;v_audit:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(coalesce(v_previous,'GENESIS')||':'||p.id::text||':FINANCE_PERIOD_CALCULATION_QUEUED:'||v_payload_hash||':'||p_correlation_id::text,'UTF8'),'sha256'),'hex');insert into finance.audit_events(legal_entity_id,actor_id,actor_type,action_code,subject_type,subject_id,decision,after_hash,previous_integrity_hash,integrity_hash,safe_context,correlation_id) values(p.legal_entity_id,p_actor_id,'USER','FINANCE_PERIOD_CALCULATION_QUEUED','finance_period',p.id,'ALLOW',v_payload_hash,v_previous,v_audit,pg_catalog.jsonb_build_object('jobId',v_job,'sourceCount',v_count,'sourceSnapshotHash',v_hash),p_correlation_id);
 return pg_catalog.jsonb_build_object('outcome','QUEUED','jobId',v_job,'periodId',p.id,'status','QUEUED','version',v_version,'sourceSnapshotHash',v_hash);
end$$;
create or replace function finance_api.finalize_finance_period_calculation(p_system_actor_id uuid,p_period_id uuid,p_job_id uuid,p_correlation_id uuid) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare p finance.finance_periods%rowtype;v_count bigint;v_pending bigint;v_missing bigint;v_material text;v_hash text;v_version bigint;v_payload jsonb;v_payload_hash text;v_previous text;v_audit text;
begin
 if not finance_private.current_period_calculation_worker_is_trusted() then raise exception using errcode='42501',message='period calculation worker denied';end if;if p_system_actor_id is null or p_period_id is null or p_job_id is null or p_correlation_id is null then raise exception using errcode='22023',message='required period finalization fields missing';end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('period-calculation:'||p_period_id::text,0));select * into p from finance.finance_periods where id=p_period_id for update;if not found then raise exception using errcode='P0002',message='finance period not found';end if;if not exists(select 1 from finance.outbox_messages om where om.id=p_job_id and om.aggregate_type='finance_period' and om.aggregate_id=p.id and om.event_type='FINANCE_PERIOD_CALCULATION_QUEUED') then raise exception using errcode='23514',message='period calculation job provenance missing';end if;if p.status='CALCULATED' then return pg_catalog.jsonb_build_object('outcome','REPLAY','periodId',p.id,'status',p.status,'version',p.version);end if;if p.scope_type<>'BRANCH' or p.status<>'SOURCE_FROZEN' then return pg_catalog.jsonb_build_object('outcome','WAITING','periodId',p.id,'status',p.status,'version',p.version);end if;
 select pg_catalog.count(*),pg_catalog.count(*) filter(where se.status<>'PROCESSED'),pg_catalog.count(*) filter(where not exists(select 1 from finance.calculation_runs cr where cr.source_event_id=se.id and cr.finance_period_id=p.id and cr.branch_id=p.branch_id and cr.run_type='LIVE' and cr.status='POSTED')),pg_catalog.string_agg(se.id::text||':'||se.event_id::text||':'||se.source_system||':'||se.event_type||':'||se.business_date::text||':'||se.payload_hash,'|' order by se.business_date,se.id) into v_count,v_pending,v_missing,v_material from finance.source_events se join finance.dealer_accounts da on da.id=p.dealer_account_id and da.dealer_legal_entity_id=se.dealer_legal_entity_id where se.legal_entity_id=p.legal_entity_id and se.branch_id=p.branch_id and se.business_date between p.period_start and p.period_end;
 v_hash:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(v_material,'UTF8'),'sha256'),'hex');if v_count=0 or v_pending>0 or v_missing>0 then return pg_catalog.jsonb_build_object('outcome','WAITING','periodId',p.id,'status',p.status,'version',p.version);end if;if v_hash<>p.source_snapshot_hash then raise exception using errcode='23514',message='frozen period source snapshot changed';end if;if exists(select 1 from finance.calculation_runs cr where cr.finance_period_id=p.id and cr.status in('STARTED','FAILED')) then return pg_catalog.jsonb_build_object('outcome','WAITING','periodId',p.id,'status',p.status,'version',p.version);end if;
 update finance.finance_periods set status='CALCULATED',version=version+1,correlation_id=p_correlation_id where id=p.id returning version into v_version;v_payload:=pg_catalog.jsonb_build_object('jobId',p_job_id,'periodId',p.id,'parentPeriodId',p.parent_period_id,'dealerAccountId',p.dealer_account_id,'branchId',p.branch_id,'sourceCount',v_count,'sourceSnapshotHash',p.source_snapshot_hash,'status','CALCULATED','version',v_version);v_payload_hash:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(v_payload::text,'UTF8'),'sha256'),'hex');insert into finance.outbox_messages(legal_entity_id,topic,event_type,aggregate_type,aggregate_id,aggregate_version,payload,payload_hash,status,correlation_id) values(p.legal_entity_id,'finance.period','FINANCE_PERIOD_CALCULATED','finance_period',p.id,v_version,v_payload,v_payload_hash,'PENDING',p_correlation_id);perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('audit:'||p.legal_entity_id::text,0));select ae.integrity_hash into v_previous from finance.audit_events ae where ae.legal_entity_id=p.legal_entity_id order by ae.created_at_utc desc,ae.id desc limit 1;v_audit:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(coalesce(v_previous,'GENESIS')||':'||p.id::text||':FINANCE_PERIOD_CALCULATED:'||v_payload_hash||':'||p_correlation_id::text,'UTF8'),'sha256'),'hex');insert into finance.audit_events(legal_entity_id,actor_id,actor_type,action_code,subject_type,subject_id,decision,after_hash,previous_integrity_hash,integrity_hash,safe_context,correlation_id) values(p.legal_entity_id,p_system_actor_id,'SYSTEM','FINANCE_PERIOD_CALCULATED','finance_period',p.id,'ALLOW',v_payload_hash,v_previous,v_audit,pg_catalog.jsonb_build_object('jobId',p_job_id,'sourceCount',v_count),p_correlation_id);return pg_catalog.jsonb_build_object('outcome','CALCULATED','periodId',p.id,'status','CALCULATED','version',v_version);
end$$;
revoke all on function finance_api.authorize_finance_period_calculation(uuid,text) from public,anon;revoke all on function finance_api.queue_finance_period_calculation(uuid,uuid,uuid,uuid,uuid,text,bigint,text,text,uuid) from public,anon,authenticated;revoke all on function finance_api.finalize_finance_period_calculation(uuid,uuid,uuid,uuid) from public,anon,authenticated;
